-- 151_replace_decision_140_2023_digital_identity_digital_contracts_digital_register_fintech_single_article_with_preamble_three_articles_attached_rules_and_three_annexes.sql
--
-- إعادة هيكلة قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (140) لسنة 2023 بتاريخ 2023/6/21 بشأن الهوية الرقمية والعقود الرقمية والسجل الرقمى ومجالات استخدام
-- التكنولوجيا المالية لمزاولة الأنشطة المالية غير المصرفية ومتطلبات الامتثال (منشور بالوقائع المصرية العدد 150 تابع (أ) فى 11 يوليو 2023).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P2 - المجموعة أ) =====
-- مخزَّن بالهجرة 037 كمادة واحدة (article_no = 1، 20761 حرفاً) تحوى القرار كله (الديباجة والمواد الثلاث والقواعد المرفقة بأقسامها الستة والملاحق الثلاثة)، فلا يمكن الاستشهاد بمادة
-- أو بند بعينه. والأهم أن المتن المخزَّن ليس نص الوقائع بل صياغة مختلفة عنه فى عشرات المواضع الجوهرية، منها على سبيل المثال: المادة الثانية تنقصها "أو موافقة"؛
-- فى الهوية الرقمية ترتيب "الصوت/الصورة" معكوس؛ فى القواعد (ثانياً/5/هـ/أ) "عنصر واحد" من عامل الوجود والحيوية بدل "ثلاثة عناصر" وبترتيب عوامل مقلوب؛
-- ثالثاً "الحفظ الإلكترونى" بدل "حفظ العقد إلكترونيا" و"من قبل المتعاقد" و"ضوابط" بدل "تطبيق ذات ضوابط"؛ رابعاً "تعديل" مكرر بدل "تجديد" فى أربعة بنود
-- و"تسجيله" بدل "حفظه" و"واسع النطاق/النظام" بدل "نطاق واسع/سجل النظام"؛ وفى الملحق (3) وصف "جدول شهري يتضمن الأعمدة التالية" من صياغة المُدخِل لا من الأصل.
-- فالنص المخزَّن لا يصلح للاستشهاد الرسمى فى هذه المواضع.
--
-- ===== المصدر والمنهجية =====
-- PDF الوقائع المصرية (16 صفحة، ص 51-66 من العدد 150 تابع (أ)، صورة ممسوحة بلا طبقة نصية، قدّمه صاحب المشروع). لا طبقة نصية فاعتُمدت القراءة البصرية للصفحات الست عشرة كلها بدقة 200 نقطة/بوصة
-- مع تكبير المواضع المشتبهة (الحوسبة الحسابية، فى الحيازة، مسؤول/مسئول، الرقمي)، ثم قوبل النص المُدخَل بمخرجات OCR مستقلة (tesseract ara) كلمة بكلمة بعد تطبيع الهمزات والياء والأرقام الهندية:
-- لم يبق فرق غير ترويسات الأقسام (وهى فى العناوين) وضجيج المسح. الأرقام والمراجع القانونية مطابقة (القوانين 131/1948 و25/1968 و159/1981 و15/2004 و10/2009 و151/2020 و194/2020 و5/2022، القرارات 58/2022 و139/2023،
-- جلسة 2023/6/21، خمس سنوات، أربعة أسابيع، RFC 5424، IETF). أُبقى إملاء الوقائع ("ى" فى "فى" و"الرقمى" و"الإلكترونى"، "ي" فى "الرقمي" داخل علامات التنصيص وعناوين الملحق (2)، "الالكترونى" بلا همزة، "الشخصية"…)؛
-- التنوين كما فى الأصل ("إلكترونيًا" و"تقنيًا" بالتنوين على الياء، و"أخذاً" و"مسبقاً" على الألف)؛ الأرقام لاتينية؛ أُسقطت علامات التشكيل الصغيرة وأُبقى تنوين الفتح. الأقسام الستة للقواعد المرفقة والملاحق الثلاثة
-- صارت مواد مستقلة بعد المادة الثالثة (أولاً ← 4 ... سادساً ← 9، ملحق 1 ← 10، ملحق 2 ← 11، ملحق 3 ← 12) بعنوانها وhierarchical_location يبيّن أنها من القواعد المرفقة بالقرار؛ جدول الملحق (3) كُتب بنداً بنداً
-- (خانات القيم فارغة فى النموذج). حُذفت ترويسة الصفحات ("الوقائع المصرية – العدد 150 تابع (أ) فى 11 يوليو سنة 2023" وأرقام الصفحات 51-66)، وسطر "مجلس إدارة الهيئة العامة للرقابة المالية" (جهة الإصدار). عنوان القرار فى hierarchical_location للديباجة.
-- التوقيع داخل المادة الثالثة. حد معلوم: همزة الألف فى بعض الكلمات ومواضع "ى/ي" لا تُحسم تماماً بدقة المسح وقد أُخذت بصورتها الأوضح؛ وهو فرق إملائى لا يمس المعنى.
--
-- ===== الهيكل =====
-- 13 صفاً، 13 نسخة (version_no = 1): ديباجة (article_no = 0) بأحد عشر اطلاعاً وجلسة المجلس، والمادة 1 (العمل بالقواعد المرفقة)، 2 (الجهات المخاطبة)، 3 (النشر والتوقيع)، ثم 4-9 أقسام القواعد
-- و10-12 الملاحق. المفتاح (1، 0) محفوظ فلا تعيد بذرة 037 إدراج المادة القديمة (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج النسخة مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2023-07-12: المادة 3 تعمل بالقرار "من اليوم التالى لتاريخ نشره"، ونشره بالوقائع المصرية العدد 150 تابع (أ) بتاريخ 2023/7/11 (ثابت بترويسة كل صفحة). لا تُمس بيانات laws.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (13 صفاً بديباجة سليمة والمادة 12 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، بقايا ترويسة،
-- نص مخزَّن قديم، محتوى المواد، إجمالى الطول 20039 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.

BEGIN;
DO $fix151$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 140 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[151] القرار 140/2023 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 13
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 12 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[151] القرار 140/2023 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[151] أُزيلت % مادة من القرار 140/2023 (القرار كله فى مادة واحدة ومتنه صياغة مخالفة لنص الوقائع فى مواضع جوهرية)', v_n;
  END IF;
END
$fix151$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة رقم 140 لسنة 2023 بتاريخ 2023/6/21 (منشور بالوقائع المصرية العدد 150 تابع (أ) فى 2023/7/11) بشأن الهوية الرقمية والعقود الرقمية والسجل الرقمى ومجالات استخدام التكنولوجيا المالية لمزاولة الأنشطة المالية غير المصرفية ومتطلبات الامتثال$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على القانون المدنى الصادر بالقانون رقم 131 لسنة 1948 ؛
وعلى قانون الإثبات فى المواد التجارية والمدنية الصادر بالقانون رقم 25 لسنة 1968 ؛
وعلى قانون الشركات المساهمة والتوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981 ؛
وعلى القانون رقم 15 لسنة 2004 بشأن تنظيم التوقيع الإلكترونى وبإنشاء هيئة تنمية صناعة تكنولوجيا المعلومات ؛
وعلى القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى قانون حماية البيانات الشخصية الصادر بالقانون رقم 151 لسنة 2020؛
وعلى قانون البنك المركزى والجهاز المصرفى الصادر بالقانون رقم 194 لسنة 2020 ؛
وعلى قانون تنظيم وتنمية استخدام التكنولوجيا المالية فى الأنشطة المالية غير المصرفية الصادر بالقانون رقم 5 لسنة 2022 ؛
وعلى قرار مجلس إدارة الهيئة رقم 58 لسنة 2022 بشأن الشروط والإجراءات المتطلبة للتأسيس والترخيص والموافقة للشركات والجهات الراغبة فى مزاولة الأنشطة المالية غير المصرفية من خلال تقنيات التكنولوجيا المالية ؛
وعلى قرار مجلس إدارة الهيئة رقم 139 لسنة 2023 بشأن التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين اللازمة لاستخدام التكنولوجيا المالية لمزاولة الأنشطة المالية غير المصرفية ؛
وعلى موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2023/6/21 ؛
قرر :$b0_0$
  FROM laws WHERE law_no = 140 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى$t1_0$, $b1_0$يعمل بالقواعد المرفقة فى شأن الهوية الرقمية والعقود الرقمية والسجل الرقمى ومجالات استخدام التكنولوجيا المالية لمزاولة الأنشطة المالية غير المصرفية ، ومتطلبات الامتثال .$b1_0$
