WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية$t2_0$, $b2_0$على الجهات والشركات الراغبة فى الحصول على ترخيص أو موافقة لمزاولة الأنشطة المالية غير المصرفية باستخدام التكنولوجيا المالية ، استيفاء المتطلبات الواردة بالقواعد المرفقة وملاحقها ، وكذلك المستندات اللازمة والتى تحددها الهيئة .$b2_0$
