)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins9_0;

WITH ins10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, $h10$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 140 لسنة 2023 - ملحق رقم (1) - متطلبات عمليات التحديد والتحقق والمصادقة$h10$, $t10_0$القواعد المرفقة - ملحق رقم (1) - متطلبات عمليات التحديد والتحقق والمصادقة$t10_0$, $b10_0$1- عند تحديد الخصائص البيومترية يجب أن يتم الآتى :
( أ ) الاعتماد على خصائص الوجه التى يتم تحديدها بواسطة الأجهزة الإلكترونية عن طريق صورة أو فيديو .
(ب) التأكد من أن الصورة أو الفيديو يتم التقاطهم مباشرة ، كما يجب أن يتم مقارنة الخصائص الملتقطة بالمرات السابقة (إن وجدت) .
2- عند تحديد الحيوية يجب التأكد أن حيوية رد فعل المتعامل تلقائية وليست ميكانيكية من خلال الاستجابة لطلبات عشوائية .
3- عند تحديد مستند إثبات الشخصية يجب أن يتم الآتى :
( أ ) التقاط صورة حية للمستند .
(ب) تحويل البيانات الملتقطة إلى بيانات رقمية من خلال تقنية التعرف على الحروف والأرقام .
(ج) التقاط الصورة الشخصية لمقارنتها بالصورة الملتقطة فى مرحلة تحديد الخصائص البيومترية .
(د) التحقق من أن المستند صحيح من خلال مراجعة خصائصه من خلال الربط مع الجهات الإدارية المختصة أو من خلال "واجهة التطبيقات القابلة للبرمجة لمنظومة الهوية الرقمية الموحدة للخدمات المالية غير المصرفية بالهيئة" ، أو بطرق أخرى لغير المقيم والتى يحددها مقدم الخدمة بعد موافقة الهيئة .
ويكون الرقم القومى أساسى للمصريين ، ويمكن إضافة مستندات إثبات شخصية أخرى .
4 - عند تحديد البريد الإلكترونى يجب إرسال رسالة والتأكد من الرد فى إطار زمنى محدد ليناسب الغرض من إثبات الحيازة ، ويكون البريد الإلكترونى الأساسى هو الحد الأدنى ، ويمكن إضافة بريد إلكترونى آخر ثانوى .
5 - عند تحديد رقم التليفون المحمول يجب أن يتم الآتى :
( أ ) إرسال رسالة نصية قصيرة والتأكد من الرد فى إطار زمنى محدد .
(ب) التحقق من أن رقم التليفون المحمول المصدر من أحد مقدمى خدمات الاتصالات المرخص لهم بتقديم خدمات الاتصالات من الجهاز القومى لتنظيم الاتصالات ، ومرتبط بنفس الرقم القومى الذى تم تحديده فى مرحلة تحديد مستند الهوية – حال وجوده – وذلك من خلال الربط مع الجهاز القومى لتنظيم الاتصالات أو من خلال "واجهة التطبيقات القابلة للبرمجة لمنظومة الهوية الرقمية الموحدة للخدمات المالية غير المصرفية بالهيئة" ، أو التحقق بطرق أخرى لغير المقيم والتى يحددها مقدم الخدمة بعد موافقة الهيئة .
ويكون رقم التليفون المحمول الأساسى هو الحد الأدنى ، ويمكن إضافة رقم تليفون محمول آخر ثانوى .
6 - عند تحديد رقم الجهاز المستخدم أو رقم الشريحة من خلال الحصول على الهوية الدولية للجهاز المحمول أو ما يكافئها ، يجب التحقق من صحة الرقم ، ويكون الجهاز الأساسى هو الحد الأدنى ، ويمكن إضافة أجهزة أخرى ثانوية .
7 - عند تحديد الموقع الجغرافى من خلال الجهاز المحمول يجب التحقق من القرب الجغرافى بالمقارنة مع العنوان البريدى الذى تم تحديده فى مرحلة تحديد الهوية ، أو العنوان البريدى المختار للمراسلة .
8 - عند تحديد الموقع السيبرانى من خلال الجهاز المحمول يجب التحقق من القرب السيبرانى بالمقارنة مع العنوان البريدى الذى تم تحديده فى مرحلة إنشاء الهوية ، أو العنوان البريدى المختار للمراسلة .
9 - عند تحديد وقت المعاملة من الجهاز المحمول يجب التحقق من القرب الزمنى بالمقارنة مع مصدر مستقل لتحديد الوقت الزمنى .
10 - عند تحديد حساب دفع غير نقدى من أحد البنوك أو مقدمى أو ميسرى الدفع الالكترونى ، والخاضعين لرقابة البنك المركزى ، يجب التأكد من حيازة حساب الدفع الإلكترونى عن طريق تحويل مبلغ صغير والتأكد من إتمامه بنجاح ، كما يجب التأكد من استخدام نفس رقم التليفون المحمول الذى تم تحديده .
11 - عند تحديد التوقيع الإلكترونى المعتمد يجب أن يتم الآتى :
( أ ) استخدام التوقيع الإلكترونى الحاصل على المفتاح الشفرى العام ، والبصمة الإلكترونية الزمنية ، وشهادة التصديق الإلكترونى ، لتحديد بيانات إنشاء التوقيع الإلكترونى .
(ب) التحقق من أن التوقيع الإلكترونى مصدر من أحد مقدمى خدمات التصديق على التوقيع الإلكترونى المصرح لهم من هيئة تنمية صناعة تكنولوجيا المعلومات ، ومرتبط بنفس الرقم القومى الذى تم تحديده فى مرحلة تحديد مستند الهوية .$b10_0$
  FROM laws WHERE law_no = 140 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins10_0;

WITH ins11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, $h11$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 140 لسنة 2023 - ملحق رقم (2) - تقنيات السجل الرقمي$h11$, $t11_0$القواعد المرفقة - ملحق رقم (2) - تقنيات السجل الرقمي$t11_0$, $b11_0$1- يجوز تطبيق السجل الرقمى بناءً على "تقنية مجموعة القيود الموزعة" ، أو "تقنية سلسلة الكتل" فى إدارة سجلات مقدمى الخدمات المالية غير المصرفية ، بما فى ذلك سجلات التعرف على العميل ، ويكون ذلك بعد الحصول على موافقة الهيئة مع تخصيص "منسق عام" لكل "سجل موزع" ، وهو المسئول عن إشراك أصحاب صلاحية التعامل التقنى على السجل فى المنظومة لتحديد احتياجات كل منهم والعمل بشكل قاطع على حلها والذى قد يتم تنفيذه من خلال "تقنية سلسلة الكتل" كنوع من أنواع السجلات الموزعة .
2- تتطلب "تقنية مجموعة القيود الموزعة" شبكة وحدات حسابية وتخزينية من نظير إلى نظير وخوارزميات لتحقيق الإجماع أو الاتفاق بحيث يتم تكرار نسخ "مجموعة القيود" بشكل موثوق عبر وحدات الشبكة الموزعة .
3- يكون نظام "مجموعة القيود الموزعة" هو قاعدة بيانات رقمية تستخدم لتخزين البيانات أو المعلومات على وحدات حسابية وتخزينية موزعة ومنتشرة عبر شبكة النظائر . ويكون لكل وحدة مشاركة فى نظام "مجموعة القيود الموزعة" سلطة متساوية التأثير ، ويجب الحصول على موافقة بالإجماع من جميع الوحدات المشاركة . وعندما توافق هذه الوحدات ويتم إجراء التغييرات ، تتلقى كل وحدة فى الشبكة اللامركزية تلقائيًا التحديثات التى تم إجراؤها على قاعدة البيانات .
4- يكون نظام الكتل المسلسلة هو "قاعدة بيانات" لمعاملات رقمية غير مركزية ، ومكررة النسخ ، وتكون القيود للمعاملات الرقمية "متفق عليها" من قبل أعضاء الشبكة النظائر ، وتختص تقنية "سلسلة الكتل" بأن هيكل البيانات يتخذ شكل كتل والتى تكون مسلسلة زمنيًا ، ومؤمنة رياضيًا باستخدام شفرة مستنبطة من معلومات المعاملة الرقمية السابقة .
5- يكون نظام الكتل المسلسلة عام ، أو خاص ، أو بدخول بناءً على إذن ، أو بغير إذن ، وقد يكون مرتبطًا بأصول مشفرة ذات حصص مشاركة مرمزة ، أو غير مرمزة .$b11_0$
  FROM laws WHERE law_no = 140 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins11_0;

WITH ins12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, $h12$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 140 لسنة 2023 - ملحق رقم (3) - نموذج متطلبات الامتثال للعمليات$h12$, $t12_0$القواعد المرفقة - ملحق رقم (3) - نموذج متطلبات الامتثال للعمليات$t12_0$, $b12_0$الأعمدة : شهر 1 ، .... ، شهر 6 ، إجمالى الفترة
البنود :
1- إجمالى عدد العمليات
2- إجمالى عدد حالات القبول
3- إجمالى عدد الحالات التى تم مراجعتها
4- عدد حالات القبول الصحيحة
5- عدد حالات الرفض الصحيحة
6- عدد حالات القبول الخاطئة
7- عدد حالات الرفض الخاطئة
8- معدل القبول الخاطئ = 6 / (6+5)
9- معدل الرفض الخاطئ = 7 / (7+4)$b12_0$
  FROM laws WHERE law_no = 140 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins12_0;

DO $verify151$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 140 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[151] القرار 140/2023 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 13 THEN RAISE EXCEPTION '[151] عدد المواد % بدل 13', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2023-07-12';
  IF v_v <> 13 THEN RAISE EXCEPTION '[151] عدد النسخ % بدل 13', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%عنصر واحد%' OR body LIKE '%جدول شهري%' OR body LIKE '%من قبل المتعاقد%' OR body LIKE '%الوقائع المصرية –%' OR body LIKE '%تابع (أ) فى 11%' OR body LIKE '%سنة 2023
%' OR body LIKE '%tluafeD%' OR body LIKE '%٢٠٢٣%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[151] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع%' AND body LIKE '%رقم 131 لسنة 1948%' AND body LIKE '%رقم 5 لسنة 2022%' AND body LIKE '%رقم 58 لسنة 2022%' AND body LIKE '%رقم 139 لسنة 2023%' AND body LIKE '%بتاريخ 2023/6/21 ؛%' AND body LIKE '%قرر :') THEN RAISE EXCEPTION '[151] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'يعمل بالقواعد المرفقة فى شأن الهوية الرقمية%' AND body LIKE '%ومتطلبات الامتثال .') THEN RAISE EXCEPTION '[151] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'على الجهات والشركات الراغبة%' AND body LIKE '%ترخيص أو موافقة لمزاولة%' AND body LIKE '%والتى تحددها الهيئة .') THEN RAISE EXCEPTION '[151] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار فى الوقائع المصرية%' AND body LIKE '%من اليوم التالى لتاريخ نشره .%' AND body LIKE '%د/ محمد فريد صالح') THEN RAISE EXCEPTION '[151] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'فى تطبيق أحكام القواعد الآتية%' AND body LIKE '%المنصة الرقمية : %' AND body LIKE '%الهوية الرقمية : %الصوت ، أو الصورة%' AND body LIKE '%الجهات المخاطبة :%' AND body LIKE '%3- الشركات الراغبة فى تقديم خدمات التعهيد%رقم 5 لسنة 2022') THEN RAISE EXCEPTION '[151] أولاً - تعريفات غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE '1- يتم ضبط الهوية الرقمية%' AND body LIKE '%ثلاثة عناصر من مجموعة عامل الوجود والحيوية على الأقل على أن يكون من بينهم الخصائص البيومترية%' AND body LIKE '%6- للهوية الرقمية ثلاث درجات من الثقة%' AND body LIKE '%فى هذا الشأن .') THEN RAISE EXCEPTION '[151] ثانياً - ضوابط الهوية غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE '1 - يلتزم مقدم الخدمة بالتحقق من هوية المتعامل%' AND body LIKE '%تطبيق ذات ضوابط الهوية الرقمية%' AND body LIKE '%2- فى حالة التعاقدات الرقمية%' AND body LIKE '%3- فى حالة التعاقدات الرقمية%المفتاحين العام والخاص .') THEN RAISE EXCEPTION '[151] ثالثاً - ضوابط العقود غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE '1- يكون لكل منصة رقمية سجل رقمى%' AND body LIKE '%وتجديد وإلغاء هوية رقمية .%' AND body LIKE '%4- يتم توفير وسائل تخزين%' AND body LIKE '%(RFC 5424)%(IETF)%' AND body LIKE '%10- يجب أن يتضمن السجل الرقمى%' AND body LIKE '%13- تحوز البيانات%حجية المحررات الرسمية%') THEN RAISE EXCEPTION '[151] رابعاً - السجل الرقمى غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE '1 - تحدد الهيئة المجالات الأساسية%' AND body LIKE '%2 - تحدد الهيئة المجالات الأخرى%المالية غير المصرفية .') THEN RAISE EXCEPTION '[151] خامساً - المجالات غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE 'يجب إعداد تقرير نصف سنوى%' AND body LIKE '%أربعة أسابيع%' AND body LIKE '%بالملحق رقم (3) .') THEN RAISE EXCEPTION '[151] سادساً - الامتثال غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0 AND body LIKE '1- عند تحديد الخصائص البيومترية%' AND body LIKE '%5 - عند تحديد رقم التليفون المحمول%' AND body LIKE '%10 - عند تحديد حساب دفع غير نقدى%' AND body LIKE '%11 - عند تحديد التوقيع الإلكترونى المعتمد%') THEN RAISE EXCEPTION '[151] الملحق 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 11 AND article_suffix_order = 0 AND body LIKE '1- يجوز تطبيق السجل الرقمى بناءً%' AND body LIKE '%5- يكون نظام الكتل المسلسلة عام%') THEN RAISE EXCEPTION '[151] الملحق 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 12 AND article_suffix_order = 0 AND body LIKE 'الأعمدة : شهر 1%' AND body LIKE '%9- معدل الرفض الخاطئ = 7 / (7+4)') THEN RAISE EXCEPTION '[151] الملحق 3 غير سليم'; END IF;
  IF v_len <> 20039 THEN RAISE EXCEPTION '[151] إجمالى طول المواد % بدل 20039', v_len; END IF;
  RAISE NOTICE '[151] القرار 140/2023: 13 مواد و13 نسخ، إجمالى % حرف', v_len;
END
$verify151$;

COMMIT;
